1	import {
2	  DirtyTrackedGraph,
3	  type CompositionId,
4	  type IBounds,
5	  type IFrameState,
6	  type IFrameStateLayer,
7	  type ITransform2D,
8	  type LayerId,
9	  type LayerType,
10	  type Tick,
11	} from "@motion-studio/shared";
12	
13	/**
14	 * One drawable node in a Scene Graph — see GLOSSARY.md "Scene Graph" and
15	 * ADR-006. Deliberately flat: Frame State layers already carry fully
16	 * evaluated (Timeline + Animation applied) local transforms, so Scene Graph
17	 * nodes have no parent/child of their own — that hierarchy lives one layer
18	 * up, in the persistent Composition Graph (`08-layer-engine/group-layer.md`).
19	 */
20	export interface ISceneGraphNode {
21	  readonly layerId: LayerId;
22	  readonly type: LayerType;
23	  readonly transform: ITransform2D;
24	  readonly opacity: number;
25	  readonly zIndex: number;
26	  readonly bounds: IBounds;
27	  readonly properties: Readonly<Record<string, unknown>>;
28	}
29	
30	/** Ephemeral, per-frame structure built from a Frame State and discarded after the frame is drawn (ADR-006). */
31	export interface ISceneGraph {
32	  readonly tick: Tick;
33	  readonly compositionId: CompositionId;
34	  readonly width: number;
35	  readonly height: number;
36	  readonly nodes: readonly ISceneGraphNode[];
37	}
38	
39	function toSceneGraphNode(layer: IFrameStateLayer): ISceneGraphNode {
40	  return {
41	    layerId: layer.layerId,
42	    type: layer.type,
43	    transform: layer.transform,
44	    opacity: layer.opacity,
45	    zIndex: layer.zIndex,
46	    bounds: layer.bounds,
47	    properties: layer.properties,
48	  };
49	}
50	
51	/** Builds the ephemeral Scene Graph for one Frame State. Pure — no dirty-tracking side effects. */
52	export function buildSceneGraph(frameState: IFrameState): ISceneGraph {
53	  return {
54	    tick: frameState.tick,
55	    compositionId: frameState.compositionId,
56	    width: frameState.width,
57	    height: frameState.height,
58	    nodes: frameState.layers.map(toSceneGraphNode),
59	  };
60	}
61	
62	function nodesEqual(a: ISceneGraphNode, b: ISceneGraphNode): boolean {
63	  return (
64	    a.opacity === b.opacity &&
65	    a.zIndex === b.zIndex &&
66	    a.transform.x === b.transform.x &&
67	    a.transform.y === b.transform.y &&
68	    a.transform.scaleX === b.transform.scaleX &&
69	    a.transform.scaleY === b.transform.scaleY &&
70	    a.transform.rotation === b.transform.rotation &&
71	    a.transform.anchorX === b.transform.anchorX &&
72	    a.transform.anchorY === b.transform.anchorY &&
73	    a.bounds.x === b.bounds.x &&
74	    a.bounds.y === b.bounds.y &&
75	    a.bounds.width === b.bounds.width &&
76	    a.bounds.height === b.bounds.height &&
77	    shallowEqualProperties(a.properties, b.properties)
78	  );
79	}
80	
81	function shallowEqualProperties(
82	  a: Readonly<Record<string, unknown>>,
83	  b: Readonly<Record<string, unknown>>,
84	): boolean {
85	  const aKeys = Object.keys(a);
86	  const bKeys = Object.keys(b);
87	  if (aKeys.length !== bKeys.length) {
88	    return false;
89	  }
90	  return aKeys.every((key) => Object.is(a[key], b[key]));
91	}
92	
93	/**
94	 * Diffs successive Scene Graphs against the generic `DirtyTrackedGraph`
95	 * primitive (ADR-005 #1) so the Rendering Engine only re-renders nodes whose
96	 * inputs actually changed since the last frame — see
97	 * `05-rendering-engine/frame-rendering.md`. Scene Graph nodes are flat, so
98	 * the accessor's parent/child edges are trivially empty; bounds/visibility
99	 * still let `queryDirtyVisible` combine dirtiness with viewport culling.
100	 */
101	export class SceneGraphDirtyTracker {
102	  private previous: ReadonlyMap<LayerId, ISceneGraphNode> | null = null;
103	  private current: ReadonlyMap<LayerId, ISceneGraphNode> = new Map();
104	
105	  readonly graph = new DirtyTrackedGraph<LayerId>({
106	    getParentId: () => null,
107	    getChildIds: () => [],
108	    getBounds: (id) => this.current.get(id)?.bounds ?? { x: 0, y: 0, width: 0, height: 0 },
109	    isVisible: () => true,
110	  });
111	
112	  /** Call once per built Scene Graph, before querying dirty/visible nodes. */
113	  update(sceneGraph: ISceneGraph): void {
114	    this.current = new Map(sceneGraph.nodes.map((node) => [node.layerId, node]));
115	    this.graph.clearAll();
116	    if (this.previous === null) {
117	      for (const id of this.current.keys()) {
118	        this.graph.markDirty(id);
119	      }
120	    } else {
121	      const previous = this.previous;
