1	import { RenderBackend } from "@motion-studio/shared";
2	import { placeholderColor } from "./placeholder-color";
3	import type { IRenderBackend, IRenderTargetSize } from "./render-backend";
4	import { sortRenderQueue } from "./render-queue";
5	import type { ISceneGraph, ISceneGraphNode } from "./scene-graph";
6	
7	export type IGLShader = object;
8	export type IGLProgram = object;
9	export type IGLBuffer = object;
10	export type IGLUniformLocation = object;
11	
12	/**
13	 * The subset of `WebGL2RenderingContext` this backend calls, hand-rolled
14	 * (rather than the full lib.dom interface) so tests can inject a fake
15	 * without a real GPU — same pattern as `ICanvas2DContext`. GL constants
16	 * (e.g. `VERTEX_SHADER`) are read off the context itself, exactly like
17	 * real WebGL2 code does (`gl.createShader(gl.VERTEX_SHADER)`), so a real
18	 * `WebGL2RenderingContext` satisfies this interface structurally.
19	 */
20	export interface IWebGL2Context {
21	  readonly VERTEX_SHADER: number;
22	  readonly FRAGMENT_SHADER: number;
23	  readonly COMPILE_STATUS: number;
24	  readonly LINK_STATUS: number;
25	  readonly ARRAY_BUFFER: number;
26	  readonly STATIC_DRAW: number;
27	  readonly TRIANGLE_STRIP: number;
28	  readonly COLOR_BUFFER_BIT: number;
29	  readonly BLEND: number;
30	  readonly SRC_ALPHA: number;
31	  readonly ONE_MINUS_SRC_ALPHA: number;
32	  readonly FLOAT: number;
33	
34	  createShader(type: number): IGLShader | null;
35	  shaderSource(shader: IGLShader, source: string): void;
36	  compileShader(shader: IGLShader): void;
37	  getShaderParameter(shader: IGLShader, pname: number): unknown;
38	  getShaderInfoLog(shader: IGLShader): string | null;
39	  deleteShader(shader: IGLShader | null): void;
40	
41	  createProgram(): IGLProgram | null;
42	  attachShader(program: IGLProgram, shader: IGLShader): void;
43	  linkProgram(program: IGLProgram): void;
44	  getProgramParameter(program: IGLProgram, pname: number): unknown;
45	  getProgramInfoLog(program: IGLProgram): string | null;
46	  useProgram(program: IGLProgram | null): void;
47	  deleteProgram(program: IGLProgram | null): void;
48	
49	  createBuffer(): IGLBuffer | null;
50	  bindBuffer(target: number, buffer: IGLBuffer | null): void;
51	  bufferData(target: number, data: Float32Array, usage: number): void;
52	  deleteBuffer(buffer: IGLBuffer | null): void;
53	
54	  getAttribLocation(program: IGLProgram, name: string): number;
55	  enableVertexAttribArray(index: number): void;
56	  vertexAttribPointer(
57	    index: number,
58	    size: number,
59	    type: number,
60	    normalized: boolean,
61	    stride: number,
62	    offset: number,
63	  ): void;
64	
65	  getUniformLocation(program: IGLProgram, name: string): IGLUniformLocation | null;
66	  uniform1f(location: IGLUniformLocation | null, x: number): void;
67	  uniform2f(location: IGLUniformLocation | null, x: number, y: number): void;
68	  uniform4f(location: IGLUniformLocation | null, x: number, y: number, z: number, w: number): void;
69	
70	  viewport(x: number, y: number, width: number, height: number): void;
71	  clearColor(r: number, g: number, b: number, a: number): void;
72	  clear(mask: number): void;
73	  enable(cap: number): void;
74	  blendFunc(sfactor: number, dfactor: number): void;
75	  drawArrays(mode: number, first: number, count: number): void;
76	}
77	
78	export interface IWebGL2BackendDependencies {
79	  getContext(): IWebGL2Context;
80	}
81	
82	/**
83	 * Vertex shader: maps a unit quad (0..1) into `bounds`, applies the layer's
84	 * anchor/scale/rotation/translate (matching `ITransform2D`'s convention —
85	 * see `transform.ts`), then projects world space into clip space.
86	 */
87	const VERTEX_SHADER_SOURCE = `#version 300 es
88	layout(location = 0) in vec2 a_unitQuad;
89	uniform vec2 u_canvasSize;
90	uniform vec2 u_translate;
91	uniform vec2 u_scale;
92	uniform float u_rotation;
93	uniform vec2 u_boundsOrigin;
94	uniform vec2 u_boundsSize;
95	
96	void main() {
97	  vec2 local = u_boundsOrigin + a_unitQuad * u_boundsSize;
98	  vec2 scaled = local * u_scale;
99	  float c = cos(u_rotation);
100	  float s = sin(u_rotation);
101	  vec2 rotated = vec2(scaled.x * c - scaled.y * s, scaled.x * s + scaled.y * c);
102	  vec2 world = rotated + u_translate;
103	  vec2 ndc = (world / u_canvasSize) * 2.0 - 1.0;
104	  gl_Position = vec4(ndc.x, -ndc.y, 0.0, 1.0);
105	}
106	`;
107	
108	/** Fragment shader: flat color fill — see `placeholder-color.ts` for why content isn't real pixels yet. */
109	const FRAGMENT_SHADER_SOURCE = `#version 300 es
110	precision mediump float;
111	uniform vec4 u_color;
112	out vec4 fragColor;
113	
114	void main() {
115	  fragColor = u_color;
116	}
117	`;
118	
119	const UNIT_QUAD = new Float32Array([0, 0, 1, 0, 0, 1, 1, 1]);
120	
121	/**
122	 * WebGL2 backend — the fallback rung between WebGPU and Canvas2D
123	 * (`05-rendering-engine/webgl.md`). GLSL is authored here independently of
124	 * WebGPU's WGSL (`webgpu-backend.ts`) per ADR-004/shader-system.md: the two
125	 * are never auto-shared.
126	 */
127	export class WebGL2RenderBackend implements IRenderBackend {
128	  readonly kind = RenderBackend.WebGL2;
129	
130	  private readonly getContext: () => IWebGL2Context;
131	  private gl: IWebGL2Context | null = null;
132	  private program: IGLProgram | null = null;
133	  private quadBuffer: IGLBuffer | null = null;
134	  private width = 0;
135	  private height = 0;
136	
137	  constructor(dependencies: IWebGL2BackendDependencies) {
138	    this.getContext = () => dependencies.getContext();
139	  }
140	
141	  init(target: IRenderTargetSize): void {
142	    this.width = target.width;
143	    this.height = target.height;
144	    const gl = this.getContext();
145	    this.gl = gl;
146	
147	    const vertexShader = this.compileShader(gl, gl.VERTEX_SHADER, VERTEX_SHADER_SOURCE);
148	    const fragmentShader = this.compileShader(gl, gl.FRAGMENT_SHADER, FRAGMENT_SHADER_SOURCE);
149	    this.program = this.linkProgram(gl, vertexShader, fragmentShader);
150	
151	    this.quadBuffer = gl.createBuffer();
152	    gl.bindBuffer(gl.ARRAY_BUFFER, this.quadBuffer);
153	    gl.bufferData(gl.ARRAY_BUFFER, UNIT_QUAD, gl.STATIC_DRAW);
154	
155	    gl.viewport(0, 0, this.width, this.height);
156	    gl.enable(gl.BLEND);
157	    gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
158	  }
159	
160	  drawFrame(sceneGraph: ISceneGraph): void {
161	    const gl = this.requireGl();
162	    const program = this.requireProgram();
163	
164	    gl.clearColor(0, 0, 0, 0);
165	    gl.clear(gl.COLOR_BUFFER_BIT);
166	    gl.useProgram(program);
167	
168	    gl.bindBuffer(gl.ARRAY_BUFFER, this.quadBuffer);
169	    const positionLocation = gl.getAttribLocation(program, "a_unitQuad");
170	    gl.enableVertexAttribArray(positionLocation);
171	    gl.vertexAttribPointer(positionLocation, 2, gl.FLOAT, false, 0, 0);
172	
173	    this.setUniform2f(gl, program, "u_canvasSize", this.width, this.height);
174	
175	    for (const node of sortRenderQueue(sceneGraph.nodes)) {
176	      this.drawNode(gl, program, node);
177	    }
178	  }
179	
180	  dispose(): void {
181	    const gl = this.gl;
182	    if (gl) {
183	      gl.deleteProgram(this.program);
184	      gl.deleteBuffer(this.quadBuffer);
185	    }
186	    this.gl = null;
187	    this.program = null;
188	    this.quadBuffer = null;
189	  }
190	
191	  private drawNode(gl: IWebGL2Context, program: IGLProgram, node: ISceneGraphNode): void {
192	    const { r, g, b } = placeholderColor(node.layerId);
193	    const { transform, bounds } = node;
194	
195	    this.setUniform2f(gl, program, "u_translate", transform.x, transform.y);
196	    this.setUniform2f(gl, program, "u_scale", transform.scaleX, transform.scaleY);
197	    this.setUniform1f(gl, program, "u_rotation", transform.rotation);
198	    this.setUniform2f(
199	      gl,
200	      program,
201	      "u_boundsOrigin",
202	      bounds.x - transform.anchorX,
203	      bounds.y - transform.anchorY,
204	    );
205	    this.setUniform2f(gl, program, "u_boundsSize", bounds.width, bounds.height);
206	    this.setUniform4f(gl, program, "u_color", r / 255, g / 255, b / 255, node.opacity);
207	
208	    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
209	  }
210	
211	  private setUniform1f(gl: IWebGL2Context, program: IGLProgram, name: string, x: number): void {
212	    gl.uniform1f(gl.getUniformLocation(program, name), x);
213	  }
214	
215	  private setUniform2f(
216	    gl: IWebGL2Context,
217	    program: IGLProgram,
218	    name: string,
219	    x: number,
220	    y: number,
221	  ): void {
222	    gl.uniform2f(gl.getUniformLocation(program, name), x, y);
223	  }
224	
225	  private setUniform4f(
226	    gl: IWebGL2Context,
227	    program: IGLProgram,
228	    name: string,
229	    x: number,
230	    y: number,
231	    z: number,
232	    w: number,
233	  ): void {
234	    gl.uniform4f(gl.getUniformLocation(program, name), x, y, z, w);
235	  }
236	
237	  private compileShader(gl: IWebGL2Context, type: number, source: string): IGLShader {
238	    const shader = gl.createShader(type);
239	    if (!shader) {
240	      throw new Error("WebGL2RenderBackend: createShader failed");
241	    }
242	    gl.shaderSource(shader, source);
243	    gl.compileShader(shader);
244	    if (gl.getShaderParameter(shader, gl.COMPILE_STATUS) !== true) {
245	      const log = gl.getShaderInfoLog(shader);
246	      gl.deleteShader(shader);
247	      throw new Error(`WebGL2RenderBackend: shader compile failed: ${log ?? "unknown error"}`);
248	    }
249	    return shader;
250	  }
251	
252	  private linkProgram(
253	    gl: IWebGL2Context,
254	    vertexShader: IGLShader,
255	    fragmentShader: IGLShader,
256	  ): IGLProgram {
257	    const program = gl.createProgram();
258	    if (!program) {
259	      throw new Error("WebGL2RenderBackend: createProgram failed");
260	    }
261	    gl.attachShader(program, vertexShader);
262	    gl.attachShader(program, fragmentShader);
263	    gl.linkProgram(program);
264	    if (gl.getProgramParameter(program, gl.LINK_STATUS) !== true) {
