178	    const vertexBuffer = device.createBuffer({
179	      size: UNIT_QUAD.byteLength,
180	      usage: GPU_BUFFER_USAGE_VERTEX | GPU_BUFFER_USAGE_COPY_DST,
181	    });
182	    device.queue.writeBuffer(vertexBuffer, 0, UNIT_QUAD);
183	
184	    const uniformBuffer = device.createBuffer({
185	      size: UNIFORM_BUFFER_SIZE_BYTES,
186	      usage: GPU_BUFFER_USAGE_UNIFORM | GPU_BUFFER_USAGE_COPY_DST,
187	    });
