194	    this.canvasContext = canvasContext;
195	    this.pipeline = pipeline;
196	    this.vertexBuffer = vertexBuffer;
197	    this.uniformBuffer = uniformBuffer;
198	    this.bindGroup = bindGroup;
199	  }
