236	    const { r, g, b } = placeholderColor(node.layerId);
237	    const { transform, bounds } = node;
238	    const data = new Float32Array(UNIFORM_FLOAT_COUNT);
239	    data[0] = this.width;
240	    data[1] = this.height;
241	    data[2] = transform.x;
242	    data[3] = transform.y;
243	    data[4] = transform.scaleX;
244	    data[5] = transform.scaleY;
245	    data[6] = transform.rotation;
246	    data[7] = 0; // _pad0
247	    data[8] = bounds.x - transform.anchorX;
248	    data[9] = bounds.y - transform.anchorY;
249	    data[10] = bounds.width;
250	    data[11] = bounds.height;
251	    data[12] = r / 255;
252	    data[13] = g / 255;
253	    data[14] = b / 255;
254	    data[15] = node.opacity;
255	    device.queue.writeBuffer(this.uniformBuffer as IGPUBuffer, 0, data);
256	  }
257	
258	  private requireDevice(): IGPUDevice {
259	    if (!this.device) {
260	      throw new Error("WebGPURenderBackend: drawFrame called before init()");
261	    }
262	    return this.device;
263	  }
264	
265	  private requireCanvasContext(): IGPUCanvasContext {
266	    if (!this.canvasContext) {
267	      throw new Error("WebGPURenderBackend: drawFrame called before init()");
268	    }
269	    return this.canvasContext;
270	  }
271	
272	  private requirePipeline(): IGPURenderPipeline {
273	    if (!this.pipeline) {
274	      throw new Error("WebGPURenderBackend: drawFrame called before init()");
275	    }
276	    return this.pipeline;
277	  }
278	}
