1	import { AssetType, secondsToTicks } from "@motion-studio/shared";
2	import type { IAssetMetadata, IMetadataExtractor } from "@motion-studio/assets";
3	
4	/**
5	 * No real decoder pipeline exists anywhere in the project yet (flagged since
6	 * Phase 12's `IMetadataExtractor` doc comment) — this is a browser-API-only
7	 * implementation, not a WebCodecs/demuxer-backed one. Video/audio duration
8	 * comes from letting the browser's own `<video>`/`<audio>` element or
9	 * `AudioContext.decodeAudioData` load the file, not from parsing the
10	 * container ourselves.
11	 *
12	 * Asset-native `durationTicks` is computed at a fixed 30fps regardless of
13	 * the source's real frame rate — there's no "project fps" in scope at
14	 * import time, only once the asset lands on a Timeline. Whoever creates a
15	 * `TrackItem` for this asset should re-derive `durationTicks` against the
16	 * destination Composition's own fps rather than reusing this value as-is
17	 * when the two differ.
18	 */
19	const ASSET_METADATA_FPS = 30;
20	
21	function readImageMetadata(data: Uint8Array, mimeType: string): Promise<IAssetMetadata> {
22	  return createImageBitmap(new Blob([data as unknown as BlobPart], { type: mimeType })).then(
23	    (bitmap) => {
24	      const metadata: IAssetMetadata = {
25	        type: AssetType.Image,
26	        width: bitmap.width,
27	        height: bitmap.height,
28	      };
29	      bitmap.close();
30	      return metadata;
31	    },
32	  );
33	}
34	
35	function readVideoMetadata(data: Uint8Array, mimeType: string): Promise<IAssetMetadata> {
36	  return new Promise((resolve, reject) => {
37	    const url = URL.createObjectURL(new Blob([data as unknown as BlobPart], { type: mimeType }));
38	    const video = document.createElement("video");
39	    video.preload = "metadata";
40	    video.onloadedmetadata = () => {
41	      const metadata: IAssetMetadata = {
42	        type: AssetType.Video,
43	        width: video.videoWidth,
44	        height: video.videoHeight,
45	        durationTicks: secondsToTicks(video.duration, ASSET_METADATA_FPS),
46	        fps: ASSET_METADATA_FPS,
47	        // No cross-browser way to detect an audio track without decoding
48	        // elementary streams (WebCodecs demuxing, out of scope) — assumed
49	        // present. Harmless today since no waveform generator is wired.
50	        hasAudio: true,
51	      };
52	      URL.revokeObjectURL(url);
53	      resolve(metadata);
54	    };
55	    video.onerror = () => {
56	      URL.revokeObjectURL(url);
57	      reject(
58	        new Error(`Failed to read video metadata: ${video.error?.message ?? "unknown error"}`),
59	      );
60	    };
61	    video.src = url;
62	  });
63	}
64	
65	async function readAudioMetadata(data: Uint8Array): Promise<IAssetMetadata> {
66	  const context = new AudioContext();
67	  try {
68	    const buffer = await context.decodeAudioData(data.slice().buffer as ArrayBuffer);
69	    return {
70	      type: AssetType.Audio,
71	      durationTicks: secondsToTicks(buffer.duration, ASSET_METADATA_FPS),
72	      sampleRate: buffer.sampleRate,
73	      numberOfChannels: buffer.numberOfChannels,
74	    };
75	  } finally {
76	    await context.close();
77	  }
78	}
