80	/**
81	 * Reads the family name straight out of the SFNT `name` table (nameID 1),
82	 * preferring a Windows/UTF-16BE record, falling back to Mac/ASCII. Only
83	 * works for raw TTF/OTF bytes — WOFF/WOFF2 wrap the same tables in
84	 * zlib/brotli compression, which would need a real decompression
85	 * dependency to unpack, so those report "Unknown" rather than guessing.
86	 */
87	function readFontMetadata(data: Uint8Array): IAssetMetadata {
88	  const family = parseSfntFamilyName(data) ?? "Unknown";
89	  return { type: AssetType.Font, family };
90	}
91	
92	const SFNT_TAGS = new Set([0x00010000, 0x4f54544f /* "OTTO" */, 0x74727565 /* "true" */]);
93	
94	function parseSfntFamilyName(data: Uint8Array): string | undefined {
95	  if (data.byteLength < 12) {
96	    return undefined;
97	  }
98	  const view = new DataView(data.buffer, data.byteOffset, data.byteLength);
99	  if (!SFNT_TAGS.has(view.getUint32(0))) {
100	    return undefined;
101	  }
102	  const numTables = view.getUint16(4);
103	  let nameTableOffset: number | undefined;
104	  for (let i = 0; i < numTables; i++) {
105	    const recordOffset = 12 + i * 16;
106	    if (recordOffset + 16 > data.byteLength) {
107	      break;
108	    }
109	    const tag = view.getUint32(recordOffset);
110	    if (tag === 0x6e616d65 /* "name" */) {
111	      nameTableOffset = view.getUint32(recordOffset + 8);
112	      break;
113	    }
114	  }
115	  if (nameTableOffset === undefined) {
116	    return undefined;
117	  }
118	
119	  const count = view.getUint16(nameTableOffset + 2);
120	  const stringAreaOffset = nameTableOffset + view.getUint16(nameTableOffset + 4);
121	  let macRecord: { offset: number; length: number } | undefined;
122	  for (let i = 0; i < count; i++) {
123	    const recordOffset = nameTableOffset + 6 + i * 12;
124	    const platformId = view.getUint16(recordOffset);
125	    const nameId = view.getUint16(recordOffset + 6);
126	    if (nameId !== 1) {
127	      continue;
128	    }
129	    const length = view.getUint16(recordOffset + 8);
130	    const offset = stringAreaOffset + view.getUint16(recordOffset + 10);
131	    if (platformId === 3) {
132	      return new TextDecoder("utf-16be").decode(data.slice(offset, offset + length));
133	    }
134	    if (platformId === 1) {
135	      macRecord = { offset, length };
136	    }
