1	"use client";
2	
3	import { useEffect, useRef, useState, type PointerEvent as ReactPointerEvent } from "react";
4	import { RenderingEngine, worldBounds, type IRenderBackend } from "@motion-studio/rendering";
5	import type { IFrameState } from "@motion-studio/shared";
6	import { useEditorKernel } from "../editor-kernel-provider";
7	import { useCanvasStore } from "../../state/use-canvas-store";
8	import { useTimelineStore } from "../../state/use-timeline-store";
9	import { useEngineRevisionStore } from "../../state/use-engine-revision-store";
10	import { createRenderBackend } from "../../editor-kernel/render-backend-factory";
11	import { buildFrameState } from "../../editor-kernel/frame-state-builder";
12	
13	/**
14	 * Hosts the real `RenderingEngine`/`IRenderBackend` pipeline
15	 * (`ARCHITECTURE.md` §4 Frame State → pixels) against an actual
16	 * `<canvas>`. `RenderingEngine`'s lifecycle is owned here, not by
17	 * `AppEngine` — it needs the real canvas element, which only exists once
18	 * this component mounts (see `EditorKernel`'s doc comment). Content is
19	 * placeholder colored rects (`placeholder-color.ts`) regardless of which
20	 * backend wins the fallback chain — no decoder pipeline exists anywhere in
21	 * the project yet.
22	 */
23	export function CanvasPanel(): JSX.Element {
24	  const kernel = useEditorKernel();
25	  const containerRef = useRef<HTMLDivElement>(null);
26	  const canvasRef = useRef<HTMLCanvasElement>(null);
27	  const overlayRef = useRef<HTMLCanvasElement>(null);
28	  const renderingEngineRef = useRef<RenderingEngine | null>(null);
29	  const backendRef = useRef<IRenderBackend | null>(null);
30	  const lastFrameStateRef = useRef<IFrameState | null>(null);
31	  const revision = useEngineRevisionStore((state) => state.revision);
32	  const selection = useTimelineStore((state) => state.selection);
33	  const select = useTimelineStore((state) => state.select);
34	  const showOverlays = useCanvasStore((state) => state.showOverlays);
35	  const [containerSize, setContainerSize] = useState({ width: 0, height: 0 });
36	
37	  const composition = kernel.timelineEngine.requireComposition(kernel.defaultCompositionId);
38	
39	  // CSS `aspect-ratio` + `max-width/max-height: 100%` can't jointly solve
40	  // "fit within this box preserving ratio" the way `object-fit: contain`
41	  // does for replaced elements — browsers resolve width first (filling the
42	  // available space), derive height from the ratio, then clip it against
43	  // max-height without re-deriving width, so a non-square composition (or a
44	  // container that isn't already the right ratio) overflows one axis and
45	  // gets silently clipped by overflow-hidden instead of shrinking to fit.
46	  // Measuring the container and computing the frame's pixel size ourselves
47	  // (the same contain-fit math object-fit:contain does internally) is the
48	  // only way to actually center a same-ratio box inside it.
49	  useEffect(() => {
50	    const container = containerRef.current;
51	    if (!container) {
52	      return;
53	    }
54	    const observer = new ResizeObserver((entries) => {
55	      const entry = entries[0];
56	      if (!entry) {
57	        return;
58	      }
59	      const { width, height } = entry.contentRect;
60	      setContainerSize({ width, height });
61	    });
62	    observer.observe(container);
63	    return () => observer.disconnect();
64	  }, []);
65	
66	  const scale =
67	    containerSize.width > 0 && containerSize.height > 0
68	      ? Math.min(containerSize.width / composition.width, containerSize.height / composition.height)
69	      : 0;
70	  const frameWidth = composition.width * scale;
71	  const frameHeight = composition.height * scale;
72	
73	  const renderCurrentFrame = (): void => {
74	    const engine = renderingEngineRef.current;
75	    if (!engine) {
76	      return;
77	    }
78	    const frameState = buildFrameState(
79	      kernel.playback.currentTick,
80	      kernel.defaultCompositionId,
81	      kernel.timelineEngine,
82	      kernel.layerEngine,
83	      kernel.animationEngine,
84	    );
85	    lastFrameStateRef.current = frameState;
86	    void engine.renderFrame(frameState);
87	    drawOverlay(frameState);
88	  };
89	
90	  const drawOverlay = (frameState: IFrameState): void => {
91	    const overlay = overlayRef.current;
92	    const ctx = overlay?.getContext("2d");
93	    if (!overlay || !ctx) {
94	      return;
95	    }
96	    ctx.clearRect(0, 0, overlay.width, overlay.height);
97	    if (!showOverlays) {
98	      return;
99	    }
100	    ctx.strokeStyle = "#5b8cff";
101	    ctx.lineWidth = 2;
102	    for (const layer of frameState.layers) {
103	      if (!selection.layerIds.includes(layer.layerId)) {
104	        continue;
105	      }
106	      const box = worldBounds(layer.bounds, layer.transform);
107	      ctx.strokeRect(box.x, box.y, box.width, box.height);
108	    }
109	  };
110	
111	  useEffect(() => {
112	    let cancelled = false;
113	
114	    createRenderBackend(canvasRef.current!)
115	      .then(async (backend) => {
116	        if (cancelled) {
117	          await backend.dispose();
118	          return;
119	        }
120	        backendRef.current = backend;
121	        const engine = new RenderingEngine(backend);
122	        await engine.setTarget({ width: composition.width, height: composition.height });
123	        renderingEngineRef.current = engine;
124	        renderCurrentFrame();
125	      })
126	      .catch((error: unknown) => {
127	        console.error("CanvasPanel: failed to create render backend", error);
128	      });
129	
130	    return () => {
131	      cancelled = true;
132	      void renderingEngineRef.current?.dispose();
133	      renderingEngineRef.current = null;
134	      backendRef.current = null;
135	    };
136	  }, [kernel]);
137	
138	  // Re-subscribes on every dependency change so the tick listener's closure
139	  // never reads stale `selection`/`showOverlays` — cheap, since subscribing
140	  // is just a Set add/remove, and it also repaints immediately (covers a
141	  // Command executing, selection changing, or overlay toggle while paused).
142	  useEffect(() => {
143	    renderCurrentFrame();
144	    return kernel.playback.onTick(() => renderCurrentFrame());
145	  }, [kernel, revision, selection, showOverlays]);
146	
147	  // The backend caches width/height inside init() (WebGPU bakes it into the
148	  // NDC-conversion uniform, Canvas2D uses it for clearRect) — the mount
149	  // effect above only calls it once, so a later frame size change (the
150	  // Toolbar's FrameSizeControl) needs its own re-init or the backend keeps
151	  // drawing at the old size onto a canvas element React has already resized.
152	  useEffect(() => {
153	    const engine = renderingEngineRef.current;
154	    if (!engine) {
155	      return;
156	    }
157	    void engine
